/* eslint-disable max-len, max-params */

'use strict';

// MODULES //

var format = require( '@stdlib/string/format' );
var max = require( '@stdlib/math/base/special/max' );
var isOperationSide = require( '@stdlib/blas/base/assert/is-operation-side' );
var isMatrixTranspose = require( '@stdlib/blas/base/assert/is-transpose-operation' );
var base = require( './base.js' );


// MAIN //

/**
* Applies an orthogonal matrix `Q`, formed from Householder reflectors returned by `DGELQF`, to overwrite matrix `C` by multiplying from the left or right with `Q` or `Q^T` using alternative indexing semantics.
*
* ## Notes
*
* -   `Q` is a real orthogonal matrix defined as the product of k elementary reflectors, Q = H(k) . . . H(2) H(1) as returned by `DGELQF`.
*
* -   `Q` is of order `M` if SIDE = 'left' and of order `N` if SIDE = 'R'.
*
* -   `DORMQR` overwrites the general real `M` by `N` matrix `C` with,
*
*     -   `Q * C`  if SIDE = 'left' and TRANS = 'no-transpose', or
*     -   `Q^T * C`  if SIDE = 'left' and TRANS = 'transpose', or
*     -   `C * Q`  if SIDE = 'right' and TRANS = 'no-transpose', or
*     -   `C * Q^T` if SIDE = 'right' and TRANS = 'transpose'.
*
* -   `WORK` must have length, `LWORK >= max(1,N)` if SIDE = `left`, and `LWORK >= max(1,M)` if SIDE = `right`.
*
* @param {string} side - specifies the side of multiplication with `C`
* @param {string} trans - `'no-transpose'` for `Q`, `'transpose'` for `Q^T`
* @param {NonNegativeInteger} M - number of rows of `C`
* @param {NonNegativeInteger} N - number of columns of `C`
* @param {NonNegativeInteger} K - number of elementary reflectors
* @param {Float64Array} A - reflector vectors from `DGELQF`
* @param {integer} strideA1 - stride of the first dimension of A
* @param {integer} strideA2 - stride of the second dimension of A
* @param {NonNegativeInteger} offsetA - starting index for A
* @param {Float64Array} TAU - scalar factors of reflectors
* @param {integer} strideTAU - stride for TAU
* @param {NonNegativeInteger} offsetTAU - starting index for TAU
* @param {Float64Array} C - input/output matrix
* @param {integer} strideC1 - stride of the first dimension of `C`
* @param {integer} strideC2 - stride of the second dimension of `C`
* @param {NonNegativeInteger} offsetC - starting index for `C`
* @param {Float64Array} WORK - workspace array
* @param {integer} strideWORK - stride for `WORK`
* @param {NonNegativeInteger} offsetWORK - starting index for `WORK`
* @param {NonNegativeInteger} LWORK - dimension of the array `WORK`
* @throws {TypeError} first argument must be a valid side
* @throws {TypeError} second argument must be a valid transpose operation
* @throws {RangeError} third argument must be a non-negative integer
* @throws {RangeError} fourth argument must be a non-negative integer
* @throws {RangeError} fifth argument must be a non-negative integer
* @throws {RangeError} fifth argument must be smaller than the order of `Q`
* @throws {RangeError} nineteenth argument must be a valid `LWORK` value
* @returns {integer} status code (0 if successful)
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1, 0, 0 ] );
* var TAU = new Float64Array( [ 2 ] );
* var C = new Float64Array( [ 1, 3, 5, 2, 4, 6 ] );
* var WORK = new Float64Array( 64 );
*
* var info = dormlq( 'left', 'no-transpose', 2, 3, 1, A, 2, 1, 0, TAU, 1, 0, C, 3, 1, 0, WORK, 1, 0, 64 );
* // returns 0
* // C => <Float64Array>[ -1, -3, -5, 2, 4, 6 ]
* // WORK[ 0 ] => 4256
* // WORK[ 1 ] => 3
* // WORK[ 2 ] => 5
*/
function dormlq( side, trans, M, N, K, A, strideA1, strideA2, offsetA, TAU, strideTAU, offsetTAU, C, strideC1, strideC2, offsetC, WORK, strideWORK, offsetWORK, LWORK ) {
	if ( !isOperationSide( side ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid operation side. Value: `%s`.', side ) );
	}
	if ( !isMatrixTranspose( trans ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a valid transpose operation. Value: `%s`.', trans ) );
	}
	if ( M < 0 ) {
		throw new RangeError( format( 'invalid argument. Third argument must be a nonnegative integer. Value: `%d`.', M ) );
	}
	if ( N < 0 ) {
		throw new RangeError( format( 'invalid argument. Fourth argument must be a nonnegative integer. Value: `%d`.', N ) );
	}
	if ( K < 0 ) {
		throw new RangeError( format( 'invalid argument. Fifth argument must be a nonnegative integer. Value: `%d`.', K ) );
	}
	if ( side === 'left' ) {
		if ( K > M ) {
			throw new RangeError( format( 'invalid argument. Fifth argument must be smaller than the order of `Q`. Value: `%d`.', K ) );
		}
		if ( LWORK < max( 1, N ) && LWORK !== -1 ) {
			throw new RangeError( format( 'invalid argument. Nineteenth argument must be greater than `max(1, N)` when `SIDE = \'L\'`. Value: `%d`.', LWORK ) );
		}
	}
	if ( side === 'right' ) {
		if ( K > N ) {
			throw new RangeError( format( 'invalid argument. Fifth argument must be smaller than the order of `Q`. Value: `%d`.', K ) );
		}
		if ( LWORK < max( 1, M ) && LWORK !== -1 ) {
			throw new RangeError( format( 'invalid argument. Nineteenth argument must be greater than `max(1, M)` when `SIDE = \'R\'`. Value: `%d`.', LWORK ) );
		}
	}

	return base( side, trans, M, N, K, A, strideA1, strideA2, offsetA, TAU, strideTAU, offsetTAU, C, strideC1, strideC2, offsetC, WORK, strideWORK, offsetWORK, LWORK );
}


// EXPORTS //

module.exports = dormlq;
